package ru.pixel10a.geminiwrapper;
import android.app.Service;import android.content.Intent;import android.graphics.PixelFormat;import android.graphics.Typeface;import android.graphics.drawable.GradientDrawable;import android.os.IBinder;import android.provider.Settings;import android.view.Gravity;import android.view.MotionEvent;import android.view.View;import android.view.WindowManager;import android.widget.LinearLayout;import android.widget.TextView;
public class GeminiOverlayService extends Service{
 private WindowManager wm;private View gear,panel;private boolean expanded=false;private int sx,sy,ix,iy;private WindowManager.LayoutParams gearParams;
 public void onCreate(){super.onCreate();if(!Settings.canDrawOverlays(this)){stopSelf();return;}wm=(WindowManager)getSystemService(WINDOW_SERVICE);TextView g=new TextView(this);g.setText("⚙");g.setTextSize(25);g.setTextColor(0xFFFFFFFF);g.setGravity(Gravity.CENTER);g.setBackground(bg(0xEE202B40,dp(30)));gear=g;gearParams=params(dp(58),dp(58));gearParams.gravity=Gravity.TOP|Gravity.END;gearParams.x=dp(12);gearParams.y=dp(180);wm.addView(gear,gearParams);gear.setOnClickListener(v->toggle());gear.setOnTouchListener((v,e)->{if(e.getAction()==MotionEvent.ACTION_DOWN){sx=(int)e.getRawX();sy=(int)e.getRawY();ix=gearParams.x;iy=gearParams.y;return false;}if(e.getAction()==MotionEvent.ACTION_MOVE){int dx=(int)e.getRawX()-sx,dy=(int)e.getRawY()-sy;if(Math.abs(dx)+Math.abs(dy)>dp(10)){gearParams.x=Math.max(0,ix-dx);gearParams.y=Math.max(0,iy+dy);wm.updateViewLayout(gear,gearParams);return true;}}return false;});}
 private void toggle(){if(expanded){wm.removeView(panel);panel=null;expanded=false;}else{LinearLayout l=new LinearLayout(this);l.setOrientation(1);l.setPadding(dp(14),dp(10),dp(14),dp(10));l.setBackground(bg(0xE6222D42,dp(18)));l.addView(label("Gemini • Инструменты",true));add(l,"🎙  Голосовой ввод","ru.pixel10a.geminiwrapper.VOICE");add(l,"📄  Документы","ru.pixel10a.geminiwrapper.DOCUMENT");add(l,"📅  Календарь и напоминания","ru.pixel10a.geminiwrapper.CALENDAR");add(l,"⚙  Настройки","ru.pixel10a.geminiwrapper.SETTINGS");TextView close=label("Закрыть",false);close.setOnClickListener(v->toggle());l.addView(close);panel=l;WindowManager.LayoutParams p=params(dp(286),-2);p.gravity=Gravity.TOP|Gravity.END;p.x=dp(12);p.y=dp(248);wm.addView(panel,p);expanded=true;}}
 private void add(LinearLayout l,String s,String a){TextView t=label(s,false);t.setOnClickListener(v->{Intent i=new Intent(this,MainActivity.class);i.setAction(a);i.addFlags(Intent.FLAG_ACTIVITY_NEW_TASK);startActivity(i);toggle();});l.addView(t);}
 private TextView label(String s,boolean title){TextView t=new TextView(this);t.setText(s);t.setTextColor(0xFFF4F6FC);t.setTextSize(title?16:15);t.setTypeface(null,title?Typeface.BOLD:Typeface.NORMAL);t.setPadding(dp(9),dp(13),dp(9),dp(13));return t;}
 private GradientDrawable bg(int c,int r){GradientDrawable d=new GradientDrawable();d.setColor(c);d.setCornerRadius(r);d.setStroke(dp(1),0x668AB4F8);return d;}
 private WindowManager.LayoutParams params(int w,int h){return new WindowManager.LayoutParams(w,h,WindowManager.LayoutParams.TYPE_APPLICATION_OVERLAY,WindowManager.LayoutParams.FLAG_NOT_FOCUSABLE|WindowManager.LayoutParams.FLAG_LAYOUT_IN_SCREEN,PixelFormat.TRANSLUCENT);}
 private int dp(int n){return (int)(n*getResources().getDisplayMetrics().density+0.5f);}public void onDestroy(){if(wm!=null){if(panel!=null)wm.removeView(panel);if(gear!=null)wm.removeView(gear);}super.onDestroy();}public IBinder onBind(Intent i){return null;}
}